    "❀ 神之手：推動綠色轉型（減緩暖化）": "❀ หัตถ์พระเจ้า: ผลักดันการเปลี่ยนผ่านสีเขียว (ชะลอโลกร้อน)",
    "、捕魚": ", จับปลา",
    "、重視民生 {0}": ", ใส่ใจปากท้องประชาชน {0}",
    "、騎馬": ", ขี่ม้า",
    "《人類的黎明》：從西元前 10,000 年的狩獵採集開始": "\"รุ่งอรุณแห่งมนุษยชาติ\": เริ่มจากนักล่าและเก็บของป่าเมื่อ 10,000 ปีก่อน ค.ศ.",
    "《人類的黎明》：每條世界線都不一樣（種子已記錄在「系統」頁的開發者資訊）": "\"รุ่งอรุณแห่งมนุษยชาติ\": ทุกเส้นเวลาไม่ซ้ำกัน (seed บันทึกไว้ในข้อมูลนักพัฒนาที่หน้าระบบ)",
    "「{0}」世界上還沒有人完成，且{1}具備前置科技": "ยังไม่มีใครในโลกทำ \"{0}\" สำเร็จ และ {1} มีเงื่อนไขครบ",
    "「{0}」在這條世界線沒有發生": "\"{0}\" ไม่ได้เกิดขึ้นในเส้นเวลานี้",
    "「{0}」已有國家掌握，且{1}具備前置科技": "\"{0}\" มีบางประเทศรู้จักแล้ว และ {1} มีเงื่อนไขครบ",
    "「{0}」是怎麼來的？": "\"{0}\" มาจากไหน?",
    "「{0}」的前置技術與地理條件都具備": "เงื่อนไขและภูมิศาสตร์สำหรับ \"{0}\" พร้อมแล้ว",
    "「{0}」脫離{1}，成為獨立政治實體。": "\"{0}\" แยกตัวจาก {1} และกลายเป็นรัฐอิสระ",
    "「{0}」解散": "\"{0}\" ถูกยุบ",
    "「備份存檔」會把這個世界存成一個檔案放到你的裝置上；換手機、清除瀏覽器資料之前，或想把世界分享給朋友時使用。": "\"สำรองเซฟ\" บันทึกโลกนี้เป็นไฟล์ในอุปกรณ์ของคุณ ใช้ก่อนเปลี่ยนโทรศัพท์ ล้างข้อมูลเบราว์เซอร์ หรือเมื่ออยากแบ่งปันโลกกับเพื่อน",
    "「如果」平行世界：{0}。": "โลกคู่ขนาน \"ถ้าหาก?\": {0}",
    "「沒有你的世界」：同一個種子、不重播你的介入重跑一次，比較哪個世界先毀滅": "\"โลกที่ไม่มีคุณ\": เล่นซ้ำด้วย seed เดิมโดยไม่มีการแทรกแซงของคุณ แล้วดูว่าโลกไหนจบก่อน",
    "「沒有國家」與「允許戰爭」互相衝突：沒有國家時不存在國家間戰爭。": "\"ไม่มีรัฐ\" ขัดกับ \"อนุญาตสงคราม\": ไม่มีรัฐก็ไม่มีสงครามระหว่างรัฐ",
    "「沒有貨幣」與「存在資本主義」互相衝突：資本主義需要以貨幣計價的資本市場。": "\"ไม่มีเงิน\" ขัดกับ \"มีทุนนิยม\": ทุนนิยมต้องมีตลาดทุนที่ตั้งราคาด้วยเงิน",
    "「直接死亡」是發生當下的死亡；「之後的死亡」是它留下的長期影響（臨界點的額外升溫、核子寒冬）在之後每年多造成的死亡，依公式拆分。": "\"การเสียชีวิตโดยตรง\" คือผู้เสียชีวิตในขณะนั้น ส่วน \"การเสียชีวิตภายหลัง\" คือผู้เสียชีวิตเพิ่มในปีต่อ ๆ มาจากผลกระทบระยะยาว (ภาวะโลกร้อนเพิ่มจากจุดเปลี่ยน ฤดูหนาวนิวเคลียร์) ซึ่งแยกด้วยสูตร",
    "「讀取備份」選那個檔案就能回到這個世界。": "เลือกไฟล์นั้นใน \"โหลดข้อมูลสำรอง\" เพื่อกลับมายังโลกนี้",
    "」可以追查），每場災難都是事件，可以用「如果？": "\" เพื่อติดตามได้) และทุกภัยพิบัติเป็นเหตุการณ์ที่ \"ถ้าหาก?",
    "」平行世界重跑時，也會在同一個時間重播這次干預。": "\" เล่นซ้ำโลกคู่ขนาน การแทรกแซงนี้จะเกิดซ้ำในเวลาเดียวกัน",
    "」平行世界重跑時，也會在同一個月份重播這次干預。": "\" เล่นซ้ำโลกคู่ขนาน การแทรกแซงนี้จะเกิดซ้ำในเดือนเดียวกัน",
    "」改寫。": "\" ในตอนนี้",
    "」改寫它沒有發生。": "\" สามารถเขียนใหม่ให้ไม่เคยเกิดขึ้น",
    "」改寫（每一項都能點開追查原因）": "\" การเขียนใหม่ (แตะแต่ละรายการเพื่อติดตามสาเหตุ)",
    "」改寫，看看世界會在什麼時候、因為什麼終結。": "\" เขียนใหม่ แล้วดูว่าโลกจบเมื่อไรและเพราะอะไร",
    "」與完整紀錄）。": "\" และบันทึกทั้งหมด)",
    "」與神之手": "\" หรือหัตถ์พระเจ้า",
