    "上台後，性格只影響國家 AI 偏好哪些政策；政策能不能執行、效果如何仍由引擎決定": "เมื่อเข้ารับตำแหน่ง บุคลิกภาพมีผลเพียงต่อนโยบายที่ AI ของประเทศชอบ ส่วนนโยบายทำได้หรือไม่และได้ผลแค่ไหนยังคงตัดสินโดยเอนจิน",
