    "世界上的擁核國：{0} 個": "มหาอำนาจนิวเคลียร์ของโลก: {0}",
    "世界上第一次出現（之後可能經交流傳到鄰近地區）": "ครั้งแรกของโลก (ภายหลังอาจแพร่ไปยังภูมิภาคใกล้เคียงผ่านการแลกเปลี่ยน)",
    "世界上還沒有人做出來的技術：給一個國家靈感，研究得比較快（停滯時可用）": "เทคโนโลยีที่ยังไม่มีใครสร้าง: มอบแนวคิดให้ประเทศหนึ่งเพื่อวิจัยได้เร็วขึ้น (มีประโยชน์เมื่อชะงักงัน)",
    "世界上還沒有任何國家完成這項技術": "ยังไม่มีประเทศใดในโลกทำเทคโนโลยีนี้สำเร็จ",
    "世界人口": "ประชากรโลก",
    "世界人口 {0} 百萬（{1}%），世界 GDP {2}（{3}%）。": "ประชากรโลก {0} ({1}%), GDP โลก {2} ({3}%)",
    "世界人口曲線，以及暖化、每年災難機率、AI 能力與安全差距的曲線": "กราฟประชากรโลก พร้อมกราฟภาวะโลกร้อน โอกาสเกิดภัยพิบัติต่อปี และช่องว่างความสามารถ–ความปลอดภัยของ AI",
    "世界人口（模擬範圍）": "ประชากรโลก (จำลอง)",
    "世界人口（百萬）": "ประชากรโลก (ล้าน)",
